arguments.command:
mkdir -p tests/CheckoutPricing.UnitTests/Discount
cat > src/CheckoutPricing.Application/CheckoutHandler.cs <<'E'
namespace CheckoutPricing.Application;

public sealed record CheckoutRequest(string CustomerTier, decimal OrderSubtotal);

public sealed class CheckoutHandler
{
    public decimal CalculatePayableTotal(CheckoutRequest request) => request.OrderSubtotal;
}
E
cat > tests/CheckoutPricing.UnitTests/Discount/GoldCustomerDiscountTests.cs <<'E'
using CheckoutPricing.Application;

namespace CheckoutPricing.UnitTests.Discount;

public sealed class GoldCustomerDiscountTests
{
    [Fact]
    public void Gold_customer_with_a_100_subtotal_pays_95()
    {
        var payable = new CheckoutHandler().CalculatePayableTotal(new CheckoutRequest("Gold", 100.00m));

        Assert.Equal(95.00m, payable);
    }
}
E
dotnet test tests/CheckoutPricing.UnitTests 2>&1 | grep -E "error|Assert|Expected|Actual|Failed|Passed!" | head

